			default:
				return 0;
		}
	}

	private static int drainEffect(Prayer prayer)
	{
		switch (prayer)
		{
			case THICK_SKIN:
			case BURST_OF_STRENGTH:
			case CLARITY_OF_THOUGHT:
			case SHARP_EYE:
			case MYSTIC_WILL:
			case RAPID_RESTORE:
			case RP_RUINOUS_GRACE:
				return 1;
			case RAPID_HEAL:
			case PROTECT_ITEM:
			case PRESERVE:
			case RP_BERSERKER:
				return 2;
			case RETRIBUTION:
			case RP_WRATH:
				return 3;
			case RP_REJUVENATION:
				return 4;
			case ROCK_SKIN:
			case SUPERHUMAN_STRENGTH:
			case IMPROVED_REFLEXES:
			case HAWK_EYE:
			case MYSTIC_LORE:
			case REDEMPTION:
				return 6;
			case RP_VINDICATION:
				return 9;
			case STEEL_SKIN:
			case ULTIMATE_STRENGTH:
			case INCREDIBLE_REFLEXES:
			case PROTECT_FROM_MAGIC:
			case PROTECT_FROM_MISSILES:
			case PROTECT_FROM_MELEE:
			case EAGLE_EYE:
			case MYSTIC_MIGHT:
			case CHIVALRY:
			case DEADEYE:
			case MYSTIC_VIGOUR:
			case RP_METABOLISE:
			case RP_REBUKE:
				return 12;
			case RP_DAMPEN_MAGIC:
			case RP_DAMPEN_RANGED:
			case RP_DAMPEN_MELEE:
			case RP_FUMUS_VOW:
			case RP_UMBRA_VOW:
			case RP_CRUORS_VOW:
			case RP_GLACIES_VOW:
				return 14;
			case SMITE:
			case RP_ANCIENT_STRENGTH:
			case RP_ANCIENT_SIGHT:
			case RP_ANCIENT_WILL:
			case RP_PROTECT_ITEM:
			case RP_PURGE:
				return 18;
			case RP_TRINITAS:
				return 22;
			case PIETY:
			case ZEAL:
			case RIGOUR:
			case AUGURY:
				return 24;
			case RP_DECIMATE:
			case RP_ANNIHILATE:
			case RP_VAPORISE:
